'use strict'

const PAIRS = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
]
const WELL_FORMED = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/

function toRoman(number) {
  if (!Number.isInteger(number) || number < 1 || number > 3999) {
    throw new RangeError('toRoman takes a whole number from 1 to 3999')
  }
  let rest = number
  let out = ''
  for (const [value, letters] of PAIRS) {
    while (rest >= value) {
      out += letters
      rest -= value
    }
  }
  return out
}

function fromRoman(text) {
  if (text === '' || !WELL_FORMED.test(text)) throw new SyntaxError('not a roman numeral: ' + text)
  let total = 0
  let at = 0
  for (const [value, letters] of PAIRS) {
    while (text.startsWith(letters, at)) {
      total += value
      at += letters.length
    }
  }
  return total
}

module.exports = { toRoman, fromRoman }

